-- Independent recorded entitlements; no deduction, automatic expiry, freeze or financial refund.
CREATE TABLE entitlement_packages (
 id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),code TEXT NOT NULL CHECK(length(trim(code)) BETWEEN 1 AND 60),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,code),UNIQUE(id,store_id)
);
CREATE TABLE entitlement_package_versions (
 package_id TEXT NOT NULL,store_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),kind TEXT NOT NULL CHECK(kind IN('count','period')),status TEXT NOT NULL CHECK(status IN('active','inactive')),service_scope TEXT NOT NULL CHECK(length(trim(service_scope)) BETWEEN 1 AND 1000),source_note TEXT NOT NULL CHECK(length(trim(source_note)) BETWEEN 1 AND 1000),paid_note TEXT,gift_note TEXT,validity_note TEXT,deduction_note TEXT,freeze_note TEXT,reversal_note TEXT,refund_note TEXT,account_sequence INTEGER NOT NULL CHECK(account_sequence>=0),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 300),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(package_id,version),FOREIGN KEY(package_id,store_id) REFERENCES entitlement_packages(id,store_id)
);
CREATE TABLE entitlement_accounts (
 id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),package_id TEXT NOT NULL,package_version INTEGER NOT NULL,cycle_id TEXT NOT NULL,cycle_version INTEGER NOT NULL,plan_id TEXT,plan_version INTEGER,customer_sequence INTEGER NOT NULL CHECK(customer_sequence>=0),context_basis TEXT NOT NULL CHECK(context_basis IN('cycle','plan')),serial INTEGER NOT NULL CHECK(serial>0),account_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,account_number),UNIQUE(id,store_id),UNIQUE(id,customer_id,store_id),FOREIGN KEY(package_id,package_version) REFERENCES entitlement_package_versions(package_id,version),FOREIGN KEY(cycle_id,cycle_version) REFERENCES cycle_versions(cycle_id,version),FOREIGN KEY(plan_id,plan_version) REFERENCES training_plan_versions(plan_id,version),CHECK((plan_id IS NULL AND plan_version IS NULL AND context_basis='cycle') OR (plan_id IS NOT NULL AND plan_version IS NOT NULL AND context_basis='plan'))
);
CREATE TABLE entitlement_events (
 id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES entitlement_accounts(id),customer_id TEXT NOT NULL REFERENCES customers(id),store_id TEXT NOT NULL REFERENCES stores(id),sequence INTEGER NOT NULL CHECK(sequence>0),revision INTEGER NOT NULL CHECK(revision>0),action TEXT NOT NULL CHECK(action IN('grant','reverse')),origin TEXT NOT NULL CHECK(origin IN('paid','gift')),quantity INTEGER CHECK(quantity IS NULL OR (typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000)),source_event_id TEXT,valid_start TEXT,valid_end TEXT,basis_reference TEXT NOT NULL CHECK(length(trim(basis_reference)) BETWEEN 1 AND 120),basis_note TEXT NOT NULL CHECK(length(trim(basis_note)) BETWEEN 1 AND 1000),document_version_id TEXT REFERENCES document_versions(id),attachment_id TEXT REFERENCES attachments(id),occurred_at TEXT NOT NULL,note TEXT NOT NULL CHECK(length(trim(note)) BETWEEN 1 AND 1000),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 300),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(account_id,revision),UNIQUE(customer_id,sequence),UNIQUE(account_id,id),FOREIGN KEY(account_id,customer_id,store_id) REFERENCES entitlement_accounts(id,customer_id,store_id),FOREIGN KEY(account_id,source_event_id) REFERENCES entitlement_events(account_id,id),CHECK((action='grant' AND source_event_id IS NULL) OR (action='reverse' AND source_event_id IS NOT NULL)),CHECK((valid_start IS NULL AND valid_end IS NULL) OR (valid_start IS NOT NULL AND valid_end IS NOT NULL AND length(valid_start)=10 AND length(valid_end)=10 AND date(valid_start,'+0 days') IS valid_start AND date(valid_end,'+0 days') IS valid_end AND valid_end>=valid_start))
);
CREATE INDEX entitlement_accounts_customer ON entitlement_accounts(customer_id,created_at,id);
CREATE INDEX entitlement_event_sources ON entitlement_events(source_event_id);
CREATE TRIGGER entitlement_packages_actor BEFORE INSERT ON entitlement_packages WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('manager') AND COALESCE(s.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'entitlement live actor/time mismatch'); END;
CREATE TRIGGER entitlement_packages_no_update BEFORE UPDATE ON entitlement_packages BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_packages_no_delete BEFORE DELETE ON entitlement_packages BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_package_versions_actor BEFORE INSERT ON entitlement_package_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('manager') AND COALESCE(s.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'entitlement live actor/time mismatch'); END;
CREATE TRIGGER entitlement_package_versions_no_update BEFORE UPDATE ON entitlement_package_versions BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_package_versions_no_delete BEFORE DELETE ON entitlement_package_versions BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_accounts_actor BEFORE INSERT ON entitlement_accounts WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND u.role IN('manager','reception') AND COALESCE(s.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'entitlement live actor/time mismatch'); END;
CREATE TRIGGER entitlement_accounts_no_update BEFORE UPDATE ON entitlement_accounts BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_accounts_no_delete BEFORE DELETE ON entitlement_accounts BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_events_actor BEFORE INSERT ON entitlement_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=(SELECT store_id FROM entitlement_accounts WHERE id=NEW.account_id) AND u.role IN('manager','reception') AND COALESCE(s.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'entitlement live actor/time mismatch'); END;
CREATE TRIGGER entitlement_events_no_update BEFORE UPDATE ON entitlement_events BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_events_no_delete BEFORE DELETE ON entitlement_events BEGIN SELECT RAISE(ABORT,'immutable entitlement history'); END;
CREATE TRIGGER entitlement_package_versions_guard BEFORE INSERT ON entitlement_package_versions WHEN NEW.account_sequence!=(SELECT COALESCE(max(serial),0) FROM entitlement_accounts WHERE store_id=NEW.store_id) OR NEW.version!=(SELECT COALESCE(max(version),0)+1 FROM entitlement_package_versions WHERE package_id=NEW.package_id) OR NEW.created_at<(SELECT created_at FROM entitlement_packages WHERE id=NEW.package_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM entitlement_package_versions WHERE package_id=NEW.package_id),NEW.created_at) OR (NEW.version=1 AND NOT EXISTS(SELECT 1 FROM entitlement_packages WHERE id=NEW.package_id AND created_at=NEW.created_at AND created_by=NEW.created_by)) OR (NEW.paid_note IS NOT NULL AND length(trim(NEW.paid_note)) NOT BETWEEN 1 AND 1000) OR (NEW.gift_note IS NOT NULL AND length(trim(NEW.gift_note)) NOT BETWEEN 1 AND 1000) OR (NEW.validity_note IS NOT NULL AND length(trim(NEW.validity_note)) NOT BETWEEN 1 AND 1000) OR (NEW.deduction_note IS NOT NULL AND length(trim(NEW.deduction_note)) NOT BETWEEN 1 AND 1000) OR (NEW.freeze_note IS NOT NULL AND length(trim(NEW.freeze_note)) NOT BETWEEN 1 AND 1000) OR (NEW.reversal_note IS NOT NULL AND length(trim(NEW.reversal_note)) NOT BETWEEN 1 AND 1000) OR (NEW.refund_note IS NOT NULL AND length(trim(NEW.refund_note)) NOT BETWEEN 1 AND 1000) BEGIN SELECT RAISE(ABORT,'entitlement package version mismatch'); END;
CREATE TRIGGER entitlement_accounts_guard BEFORE INSERT ON entitlement_accounts WHEN NEW.customer_sequence!=(SELECT COALESCE(max(sequence),0) FROM entitlement_events WHERE customer_id=NEW.customer_id) OR NEW.serial!=(SELECT COALESCE(max(serial),0)+1 FROM entitlement_accounts WHERE store_id=NEW.store_id) OR NEW.account_number!=('EA-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) OR NOT EXISTS(SELECT 1 FROM customers c JOIN cycle_versions cv ON cv.customer_id=c.id WHERE c.id=NEW.customer_id AND c.store_id=NEW.store_id AND cv.cycle_id=NEW.cycle_id AND cv.version=NEW.cycle_version AND cv.type='training' AND cv.created_at<=NEW.created_at) OR NOT EXISTS(SELECT 1 FROM entitlement_package_versions p WHERE p.package_id=NEW.package_id AND p.version=NEW.package_version AND p.store_id=NEW.store_id AND p.status='active' AND p.version=(SELECT max(version) FROM entitlement_package_versions WHERE package_id=p.package_id) AND p.created_at<=NEW.created_at) OR (NEW.plan_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM training_plans p JOIN training_plan_versions v ON v.plan_id=p.id WHERE p.id=NEW.plan_id AND v.version=NEW.plan_version AND p.store_id=NEW.store_id AND p.customer_id=NEW.customer_id AND p.cycle_id=NEW.cycle_id AND p.cycle_version=NEW.cycle_version AND v.created_at<=NEW.created_at)) OR (NEW.plan_id IS NULL AND NEW.cycle_version!=(SELECT max(version) FROM cycle_versions WHERE cycle_id=NEW.cycle_id)) BEGIN SELECT RAISE(ABORT,'entitlement fixed source mismatch'); END;
CREATE TRIGGER entitlement_events_guard BEFORE INSERT ON entitlement_events WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM entitlement_events WHERE customer_id=NEW.customer_id) OR NEW.revision!=(SELECT COALESCE(max(revision),0)+1 FROM entitlement_events WHERE account_id=NEW.account_id) OR NEW.created_at<(SELECT created_at FROM entitlement_accounts WHERE id=NEW.account_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM entitlement_events WHERE account_id=NEW.account_id),NEW.created_at) OR length(NEW.occurred_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.occurred_at) IS NOT NEW.occurred_at OR NEW.occurred_at>NEW.created_at OR ((SELECT kind FROM entitlement_accounts a JOIN entitlement_package_versions p ON p.package_id=a.package_id AND p.version=a.package_version WHERE a.id=NEW.account_id)='count' AND NEW.quantity IS NULL) OR ((SELECT kind FROM entitlement_accounts a JOIN entitlement_package_versions p ON p.package_id=a.package_id AND p.version=a.package_version WHERE a.id=NEW.account_id)='period' AND (NEW.quantity IS NOT NULL OR NEW.valid_start IS NULL)) OR (NEW.revision=1 AND (NEW.action!='grant' OR NEW.sequence!=(SELECT customer_sequence+1 FROM entitlement_accounts WHERE id=NEW.account_id) OR NOT EXISTS(SELECT 1 FROM entitlement_accounts a WHERE a.id=NEW.account_id AND a.created_at=NEW.created_at AND a.created_by=NEW.created_by))) OR (NEW.action='grant' AND ((SELECT kind FROM entitlement_accounts a JOIN entitlement_package_versions p ON p.package_id=a.package_id AND p.version=a.package_version WHERE a.id=NEW.account_id)='count' AND NEW.quantity+COALESCE((SELECT sum(quantity) FROM entitlement_events WHERE account_id=NEW.account_id AND action='grant' AND origin=NEW.origin),0)>1000000000 OR NEW.document_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM document_versions d JOIN entitlement_accounts a ON a.customer_id=d.customer_id WHERE a.id=NEW.account_id AND d.id=NEW.document_version_id AND d.created_at<=NEW.created_at) OR NEW.attachment_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM attachments d JOIN entitlement_accounts a ON a.customer_id=d.customer_id WHERE a.id=NEW.account_id AND d.id=NEW.attachment_id AND d.revoked_at IS NULL AND d.created_at<=NEW.created_at))) OR (NEW.action='reverse' AND ((SELECT role FROM users WHERE id=NEW.created_by)!='manager' OR NOT EXISTS(SELECT 1 FROM entitlement_events s WHERE s.id=NEW.source_event_id AND s.account_id=NEW.account_id AND s.action='grant' AND s.origin=NEW.origin AND s.valid_start IS NEW.valid_start AND s.valid_end IS NEW.valid_end AND s.basis_reference=NEW.basis_reference AND s.basis_note=NEW.basis_note AND s.document_version_id IS NEW.document_version_id AND s.attachment_id IS NEW.attachment_id AND s.occurred_at=NEW.occurred_at AND s.created_at<=NEW.created_at) OR (SELECT kind FROM entitlement_accounts a JOIN entitlement_package_versions p ON p.package_id=a.package_id AND p.version=a.package_version WHERE a.id=NEW.account_id)='count' AND NEW.quantity+COALESCE((SELECT sum(quantity) FROM entitlement_events WHERE source_event_id=NEW.source_event_id),0)>(SELECT quantity FROM entitlement_events WHERE id=NEW.source_event_id) OR (SELECT kind FROM entitlement_accounts a JOIN entitlement_package_versions p ON p.package_id=a.package_id AND p.version=a.package_version WHERE a.id=NEW.account_id)='period' AND EXISTS(SELECT 1 FROM entitlement_events WHERE source_event_id=NEW.source_event_id))) BEGIN SELECT RAISE(ABORT,'entitlement event source or capacity mismatch'); END;
CREATE TRIGGER entitlement_events_reference BEFORE INSERT ON entitlement_events WHEN NEW.action='grant' AND EXISTS(SELECT 1 FROM entitlement_events g JOIN entitlement_accounts a ON a.id=g.account_id JOIN entitlement_accounts mine ON mine.id=NEW.account_id JOIN entitlement_package_versions p ON p.package_id=a.package_id AND p.version=a.package_version WHERE a.customer_id=mine.customer_id AND a.store_id=mine.store_id AND g.action='grant' AND g.origin=NEW.origin AND g.basis_reference=NEW.basis_reference AND ((p.kind='count' AND g.quantity>COALESCE((SELECT sum(quantity) FROM entitlement_events r WHERE r.source_event_id=g.id),0)) OR (p.kind='period' AND NOT EXISTS(SELECT 1 FROM entitlement_events r WHERE r.source_event_id=g.id)))) BEGIN SELECT RAISE(ABORT,'entitlement acquisition reference already recorded'); END;
